        }
      ]
    },
    {
      "unit_key": "CH3:3",
      "studies": [
        {
          "source_handle": "P0001",
          "contribution": "论证FWHM作为单一判据的局限性，结合Kho16旁瓣增强导致MTF偏离衍射极限的证据，倡导引入MTF以全面量化空间频率响应和图像对比度。"
        }
      ]
    },
    {
      "unit_key": "CH3:4",
      "studies": [
        {
          "source_handle": "P0001",
          "contribution": "提供基于单界面几何像差的FOV物理下限（如NA=0.5时<5µm），用于评估当前实验器件是否触及理论饱和区，补充带宽-视场关系的实证基准。"
        }
      ]
    }
  ]
}

